-- Executive KPI Phase 6: Management Review governance. Operational sources remain authoritative.
create table if not exists public.executive_management_review_cycles (
 id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), department_id text null, unit_id text null, cycle_code text not null, cycle_title text not null, cycle_type text not null, governance_level text not null, reporting_period_start timestamptz not null, reporting_period_end timestamptz not null, planned_review_date timestamptz null, required_completion_date timestamptz null, review_frequency text not null, policy_version_id text null, owner_user_id text not null, sponsor_user_id text null, coordinator_user_id text null, cycle_status text not null default 'Draft', readiness_status text not null default 'Not Checked', scope_json jsonb not null default '{}'::jsonb, notes text null, activated_at timestamptz null, completed_at timestamptz null, completed_by text null, completion_summary text null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz null, archived_by text null, archive_reason text null, unique(company_id,cycle_code), check(reporting_period_end >= reporting_period_start)
);
create table if not exists public.executive_management_review_meetings (
 id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), review_cycle_id text not null references public.executive_management_review_cycles(id), meeting_code text not null, meeting_title text not null, meeting_type text not null, meeting_status text not null default 'Draft', chairperson_user_id text not null, secretary_user_id text null, coordinator_user_id text null, executive_sponsor_user_id text null, scheduled_start_at timestamptz not null, scheduled_end_at timestamptz not null, timezone text not null, meeting_mode text not null, location text null, calendar_event_reference text null, confidentiality_level text not null default 'Internal', preparation_due_at timestamptz null, rsvp_due_at timestamptz null, agenda_template_id text null, current_package_id text null, current_minutes_id text null, quorum_policy_snapshot_json jsonb null, quorum_status text null, source_freshness_status text not null default 'Unknown', started_at timestamptz null, adjourned_at timestamptz null, completed_at timestamptz null, cancelled_at timestamptz null, cancellation_reason text null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,meeting_code), check(scheduled_end_at > scheduled_start_at)
);
create table if not exists public.executive_management_review_participants (
 id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), meeting_id text not null references public.executive_management_review_meetings(id), user_id text not null, participant_role text not null, required boolean not null default false, invitation_status text not null default 'Pending', rsvp_status text not null default 'No Response', attendance_status text not null default 'Not Recorded', invited_by text null, invited_at timestamptz null, responded_at timestamptz null, attendance_recorded_by text null, attendance_recorded_at timestamptz null, apology_note text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(meeting_id,user_id)
);
create table if not exists public.executive_management_review_agenda_templates (id text primary key, company_id text null references public."Tenant"(id), site_id text null references public."Site"(id), template_code text not null, template_title text not null, review_type text null, governance_level text null, template_version integer not null default 1, sections_json jsonb not null default '[]'::jsonb, active boolean not null default true, system_defined boolean not null default false, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz null, unique(company_id,site_id,template_code,template_version));
create table if not exists public.executive_management_review_agenda_items (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), meeting_id text not null references public.executive_management_review_meetings(id), agenda_code text not null, agenda_category text not null, agenda_title text not null, agenda_description text null, agenda_order integer not null, scheduled_duration_minutes integer null, presenter_user_id text null, owner_user_id text null, psm_element_id text null, source_module text null, source_record_type text null, source_record_id text null, kpi_definition_id text null, critical_risk_case_id text null, escalation_id text null, universal_action_id text null, decision_required boolean not null default false, criticality text null, priority text null, agenda_status text not null default 'Open', discussion_summary text null, disposition_reason text null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(meeting_id,agenda_code));
create table if not exists public.executive_management_review_packages (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), meeting_id text not null references public.executive_management_review_meetings(id), review_cycle_id text not null references public.executive_management_review_cycles(id), package_code text not null, package_title text not null, package_type text not null, package_status text not null default 'Draft', confidentiality_level text not null default 'Internal', kpi_snapshot_id text null, aggregation_run_id text null, current_version_number integer not null default 0, included_modules_json jsonb not null default '[]'::jsonb, excluded_modules_json jsonb not null default '[]'::jsonb, restricted_modules_json jsonb not null default '[]'::jsonb, section_config_json jsonb not null default '{}'::jsonb, readiness_status text not null default 'Not Checked', readiness_results_json jsonb null, source_count integer not null default 0, restricted_source_count integer not null default 0, excluded_source_count integer not null default 0, stale_source_count integer not null default 0, manifest_hash text null, generated_by text null, generated_at timestamptz null, published_by text null, published_at timestamptz null, locked_by text null, locked_at timestamptz null, stale_status text not null default 'Current', stale_reason text null, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,package_code));
create table if not exists public.executive_management_review_package_versions (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), package_id text not null references public.executive_management_review_packages(id), version_number integer not null, version_status text not null default 'Draft', source_snapshot_json jsonb not null default '{}'::jsonb, manifest_json jsonb not null default '{}'::jsonb, content_config_snapshot_json jsonb not null default '{}'::jsonb, file_reference_id text null, document_reference_id text null, content_hash text null, generated_by text null, generated_at timestamptz not null default now(), approval_package_id text null, superseded_by_version_id text null, superseded_at timestamptz null, version_reason text null, created_at timestamptz not null default now(), unique(package_id,version_number));
create table if not exists public.executive_management_review_package_sources (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), package_version_id text not null references public.executive_management_review_package_versions(id), source_module text not null, source_record_type text not null, source_record_id text not null, source_updated_at timestamptz null, included boolean not null default true, excluded_reason text null, restricted boolean not null default false, evidence_status text null, source_freshness_status text not null default 'Unknown', source_snapshot_json jsonb null, created_at timestamptz not null default now());
create table if not exists public.executive_management_review_minutes (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), meeting_id text not null references public.executive_management_review_meetings(id), minutes_code text not null, current_version_number integer not null default 0, minutes_status text not null default 'Draft', summary text null, attendance_snapshot_json jsonb not null default '[]'::jsonb, agenda_summary_json jsonb not null default '[]'::jsonb, decision_summary_json jsonb not null default '[]'::jsonb, commitment_summary_json jsonb not null default '[]'::jsonb, carry_forward_summary_json jsonb not null default '[]'::jsonb, source_package_version_id text null, approval_package_id text null, approved_by text null, approved_at timestamptz null, locked_by text null, locked_at timestamptz null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,minutes_code));
create table if not exists public.executive_management_review_minutes_versions (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), minutes_id text not null references public.executive_management_review_minutes(id), version_number integer not null, content_snapshot_json jsonb not null default '{}'::jsonb, content_hash text null, file_reference_id text null, document_reference_id text null, version_status text not null default 'Draft', change_reason text null, approval_package_id text null, esignature_reference_id text null, generated_by text null, generated_at timestamptz not null default now(), approved_at timestamptz null, created_at timestamptz not null default now(), unique(minutes_id,version_number));
alter table public.executive_management_decisions add column if not exists decision_title text null, add column if not exists decision_description text null, add column if not exists review_cycle_id text null, add column if not exists meeting_id text null, add column if not exists agenda_item_id text null, add column if not exists critical_risk_case_id text null, add column if not exists source_module text null, add column if not exists source_record_type text null, add column if not exists source_record_id text null, add column if not exists decision_authority_role text null, add column if not exists criticality text null, add column if not exists approval_required boolean not null default false, add column if not exists implementation_status text not null default 'Not Started', add column if not exists verification_required boolean not null default false, add column if not exists verification_status text null, add column if not exists responsible_owner_user_id text null, add column if not exists closure_at timestamptz null, add column if not exists closure_reason text null, add column if not exists superseded_by_decision_id text null;
create table if not exists public.executive_management_decision_source_links (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), decision_id text not null references public.executive_management_decisions(id), source_module text not null, source_record_type text not null, source_record_id text not null, relationship_type text not null, restricted boolean not null default false, source_snapshot_json jsonb null, linked_by text null, linked_at timestamptz not null default now(), unique(decision_id,source_module,source_record_type,source_record_id));
create table if not exists public.executive_management_commitments (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), department_id text null, unit_id text null, commitment_code text not null, commitment_title text not null, commitment_description text not null, decision_id text null references public.executive_management_decisions(id), meeting_id text null references public.executive_management_review_meetings(id), review_cycle_id text null references public.executive_management_review_cycles(id), source_module text null, source_record_type text null, source_record_id text null, owner_user_id text not null, accountable_executive_user_id text null, priority text not null default 'Medium', criticality text null, original_due_at timestamptz null, effective_due_at timestamptz null, commitment_status text not null default 'Open', universal_action_id text null, verification_required boolean not null default false, verification_status text null, evidence_reference_id text null, escalation_id text null, completed_at timestamptz null, verified_at timestamptz null, closed_by text null, closure_reason text null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,commitment_code));
create table if not exists public.executive_management_review_carry_forward_items (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), source_cycle_id text null, source_meeting_id text null, source_agenda_item_id text null, source_decision_id text null, source_commitment_id text null, source_record_type text not null, source_record_id text not null, target_cycle_id text null, target_meeting_id text null, carry_forward_reason text not null, carried_forward_by text null, carried_forward_at timestamptz not null default now(), current_status text not null default 'Open', resolved_at timestamptz null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.executive_management_review_readiness_results (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), review_cycle_id text null, meeting_id text null, package_id text null, readiness_status text not null, validation_rules_version text not null default '1', result_details_json jsonb not null default '{}'::jsonb, blocker_count integer not null default 0, warning_count integer not null default 0, missing_required_data_count integer not null default 0, stale_source_count integer not null default 0, restricted_conflict_count integer not null default 0, checked_by text null, checked_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.executive_management_review_history_events (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), review_cycle_id text null, meeting_id text null, agenda_item_id text null, package_id text null, minutes_id text null, decision_id text null, commitment_id text null, event_type text not null, event_title text not null, event_description text null, before_value_json jsonb null, after_value_json jsonb null, actor_user_id text null, source_module text null, source_record_id text null, correlation_id text null, restricted boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.executive_management_review_policy_versions (id text primary key, company_id text not null references public."Tenant"(id), site_id text null references public."Site"(id), policy_code text not null, policy_version integer not null, review_frequency text null, required_roles_json jsonb not null default '[]'::jsonb, quorum_config_json jsonb null, readiness_rules_json jsonb not null default '{}'::jsonb, minutes_approval_required boolean not null default false, decision_approval_rules_json jsonb not null default '{}'::jsonb, signature_rules_json jsonb not null default '{}'::jsonb, followup_policy_json jsonb not null default '{}'::jsonb, carry_forward_policy_json jsonb not null default '{}'::jsonb, reminder_policy_json jsonb not null default '{}'::jsonb, effective_from timestamptz not null default now(), effective_until timestamptz null, approved_by text null, approved_at timestamptz null, created_by text null, created_at timestamptz not null default now(), unique(company_id,site_id,policy_code,policy_version));
create index if not exists emr_cycle_scope_status_idx on public.executive_management_review_cycles(company_id,site_id,cycle_status); create index if not exists emr_meeting_status_idx on public.executive_management_review_meetings(company_id,site_id,meeting_status); create index if not exists emr_meeting_time_idx on public.executive_management_review_meetings(review_cycle_id,scheduled_start_at); create index if not exists emr_commitment_due_idx on public.executive_management_commitments(company_id,effective_due_at,commitment_status); create index if not exists emr_history_idx on public.executive_management_review_history_events(company_id,review_cycle_id,created_at desc);
do $$
declare
  permission_key text;
begin
  foreach permission_key in array array[
    'executive.management_review.view', 'executive.management_review.dashboard.view', 'executive.management_review.readiness.view', 'executive.management_review.settings.view', 'executive.management_review.settings.edit', 'executive.management_review.cycle.view', 'executive.management_review.cycle.create', 'executive.management_review.cycle.edit', 'executive.management_review.cycle.activate', 'executive.management_review.cycle.complete', 'executive.management_review.cycle.reopen', 'executive.management_review.cycle.archive', 'executive.management_review.meeting.view', 'executive.management_review.meeting.create', 'executive.management_review.meeting.edit', 'executive.management_review.meeting.schedule', 'executive.management_review.meeting.reschedule', 'executive.management_review.meeting.cancel', 'executive.management_review.meeting.start', 'executive.management_review.meeting.record_attendance', 'executive.management_review.meeting.record_discussion', 'executive.management_review.meeting.adjourn', 'executive.management_review.meeting.complete', 'executive.management_review.agenda.view', 'executive.management_review.agenda.create', 'executive.management_review.agenda.edit', 'executive.management_review.agenda.reorder', 'executive.management_review.agenda.defer', 'executive.management_review.agenda.carry_forward', 'executive.management_review.agenda.template.manage', 'executive.management_review.package.view', 'executive.management_review.package.create', 'executive.management_review.package.generate', 'executive.management_review.package.publish', 'executive.management_review.package.download', 'executive.management_review.package.regenerate', 'executive.management_review.package.access_log.view', 'executive.management_review.package.restricted.view', 'executive.management_review.minutes.view', 'executive.management_review.minutes.create', 'executive.management_review.minutes.edit', 'executive.management_review.minutes.submit', 'executive.management_review.minutes.approve', 'executive.management_review.minutes.lock', 'executive.management_review.minutes.version.view', 'executive.management_review.decision.view', 'executive.management_review.decision.create', 'executive.management_review.decision.edit', 'executive.management_review.decision.submit', 'executive.management_review.decision.approve', 'executive.management_review.decision.supersede', 'executive.management_review.decision.verify', 'executive.management_review.decision.history.view', 'executive.management_review.commitment.view', 'executive.management_review.commitment.create', 'executive.management_review.commitment.assign', 'executive.management_review.commitment.followup', 'executive.management_review.commitment.escalate', 'executive.management_review.commitment.verify', 'executive.management_review.commitment.close', 'executive.management_review.commitment.carry_forward', 'executive.management_review.history.view', 'executive.management_review.audit.view', 'executive.management_review.restricted_source.view'
  ] loop
    insert into public."Permission" ("id", "tenantId", "key", "moduleKey", "label")
    select gen_random_uuid()::text, tenant."id", permission_key, 'EXECUTIVE', permission_key
    from public."Tenant" tenant
    where not exists (
      select 1 from public."Permission" permission
      where permission."tenantId" = tenant."id"
        and permission."key" = permission_key
    );
  end loop;
end $$;
